#include <stdio.h>

int main(void) {
    int pressure;
    scanf("%d", &pressure);
    if (pressure >= 95) {
        printf("Airlock: OPEN\n");
    } else {
        printf("Airlock: HOLD\n");
    }
    printf("Pressure was %d\n", pressure);
    return 0;
}

