#include <stdio.h>

int main(void) {
    int deck;
    scanf("%d", &deck);
    switch (deck) {
        case 1:
            printf("Bridge\n");
            break;
        case 2:
            printf("Engines\n");
            break;
        default:
            printf("Unknown deck\n");
    }
    int floors = deck > 0 ? deck : 0;
    printf("Floors up: %d\n", floors);
    return 0;
}

